if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.13 — Financial History & Trend Intelligence */
function tuff_beatz_v1413_months($count=12){$out=array();$now=current_time('timestamp');for($i=$count-1;$i>=0;$i--){$ts=strtotime('-'.$i.' months',$now);$out[]=array('year'=>(int)wp_date('Y',$ts),'month'=>(int)wp_date('n',$ts),'key'=>wp_date('Y-m',$ts),'label'=>wp_date('M Y',$ts));}return $out;}
function tuff_beatz_v1413_month_snapshot($year,$month){$collected=function_exists('tuff_beatz_v1410_monthly_collected')?tuff_beatz_v1410_monthly_collected($year,$month):0.0;$over=function_exists('tuff_beatz_v1412_overhead')?tuff_beatz_v1412_overhead($year,$month):array('total'=>0,'recorded'=>false);$direct=0.0;$covered_paid=0.0;$covered=0;$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>500,'fields'=>'ids'));foreach($q->posts as $id){if(!function_exists('tuff_beatz_v1411_cost_basis'))break;$c=tuff_beatz_v1411_cost_basis($id);if(!$c['recorded'])continue;$payments=function_exists('tuff_beatz_payment_data')?tuff_beatz_payment_data($id):array();$month_paid=0.0;foreach($payments as $p){if(($p['status']??'')!=='paid'||empty($p['date']))continue;$ts=strtotime((string)$p['date']);if($ts&&(int)wp_date('Y',$ts)===(int)$year&&(int)wp_date('n',$ts)===(int)$month)$month_paid+=(float)($p['amount']??0);}if($month_paid<=0)continue;$covered++;$covered_paid+=$month_paid;$direct+=(float)$c['total'];}$operating=$covered_paid-$direct-(float)($over['total']??0);$margin=$covered_paid>0?($operating/$covered_paid)*100:null;$coverage=$collected>0?min(100,($covered_paid/$collected)*100):0;return array('collected'=>$collected,'covered_collected'=>$covered_paid,'direct_cost'=>$direct,'overhead'=>(float)($over['total']??0),'operating_contribution'=>$operating,'margin'=>$margin,'coverage'=>$coverage,'covered_projects'=>$covered,'overhead_recorded'=>!empty($over['recorded']));}
function tuff_beatz_v1413_trends($count=12){$rows=array();foreach(tuff_beatz_v1413_months($count) as $m)$rows[]=array_merge($m,tuff_beatz_v1413_month_snapshot($m['year'],$m['month']));$n=count($rows);$cur=$n?$rows[$n-1]:array();$prev=$n>1?$rows[$n-2]:array();$sum=function($key)use($rows){$v=0;foreach($rows as $r)$v+=(float)($r[$key]??0);return $v;};$recent=array_slice($rows,max(0,$n-3));$avg3=0;if($recent){foreach($recent as $r)$avg3+=(float)$r['collected'];$avg3/=count($recent);}$change=function($a,$b){return $b>0?(($a-$b)/$b)*100:null;};$best=null;foreach($rows as $r)if($best===null||$r['operating_contribution']>$best['operating_contribution'])$best=$r;return array('rows'=>$rows,'current'=>$cur,'previous'=>$prev,'revenue_change'=>$change((float)($cur['collected']??0),(float)($prev['collected']??0)),'operating_change'=>$change((float)($cur['operating_contribution']??0),(float)($prev['operating_contribution']??0)),'rolling3_collected'=>$avg3,'period_collected'=>$sum('collected'),'period_overhead'=>$sum('overhead'),'period_operating'=>$sum('operating_contribution'),'best_month'=>$best);}
function tuff_beatz_v1413_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$x=tuff_beatz_v1413_trends(12);$money=function($n){return function_exists('tuff_beatz_money')?tuff_beatz_money($n):'$'.number_format((float)$n,2);};$pct=function($n){return $n===null?'—':(($n>=0?'+':'').number_format((float)$n,1).'%');};ob_start();?><section class="tb-v1413-trends"><div class="tb-v1413-head"><div><small>FINANCIAL HISTORY • V14.13</small><h3>12-Month Business Trend</h3><p>Historical management view built from recorded payment dates, project cost coverage and monthly overhead entries.</p></div><div><span>3-MONTH AVG COLLECTIONS</span><strong><?php echo esc_html($money($x['rolling3_collected']));?></strong></div></div><div class="tb-v1413-kpis"><article><small>12-MONTH COLLECTIONS</small><strong><?php echo esc_html($money($x['period_collected']));?></strong></article><article><small>12-MONTH OVERHEAD</small><strong><?php echo esc_html($money($x['period_overhead']));?></strong></article><article><small>COVERED OPERATING CONTRIBUTION</small><strong><?php echo esc_html($money($x['period_operating']));?></strong></article><article><small>MONTH-OVER-MONTH COLLECTIONS</small><strong><?php echo esc_html($pct($x['revenue_change']));?></strong></article><article><small>MONTH-OVER-MONTH OPERATING</small><strong><?php echo esc_html($pct($x['operating_change']));?></strong></article><article><small>BEST COVERED MONTH</small><strong><?php echo esc_html($x['best_month']['label']??'—');?></strong><span><?php echo esc_html($money($x['best_month']['operating_contribution']??0));?></span></article></div><div class="tb-v1413-table"><div class="tb-v1413-row is-head"><span>Month</span><span>Collected</span><span>Overhead</span><span>Operating*</span><span>Margin*</span><span>Coverage</span></div><?php foreach(array_reverse($x['rows']) as $r):?><div class="tb-v1413-row"><span><b><?php echo esc_html($r['label']);?></b></span><span><?php echo esc_html($money($r['collected']));?></span><span><?php echo esc_html($money($r['overhead']));?></span><span><?php echo esc_html($money($r['operating_contribution']));?></span><span><?php echo $r['margin']===null?'—':esc_html(number_format((float)$r['margin'],1).'%');?></span><span><?php echo esc_html(number_format((float)$r['coverage'],0).'%');?></span></div><?php endforeach;?></div><p class="tb-v1413-foot">* Operating contribution and margin include only collections tied to projects with a recorded cost basis, less the month’s entered overhead. Historical project cost records are not time-accrued, so these trends are management intelligence rather than formal financial statements.</p></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var anchor=document.querySelector('.tb-v1412-overhead')||document.querySelector('.tb-v1411-profit');if(!anchor||document.querySelector('.tb-v1413-trends'))return;var box=document.createElement('div');box.innerHTML=<?php echo wp_json_encode($html);?>;anchor.insertAdjacentElement('afterend',box.firstElementChild);var eye=document.querySelector('.tb-biz-hero .eyebrow');if(eye)eye.textContent='TUFF BEATZ • STUDIO BUSINESS OS V14.13';});</script><?php }
add_action('wp_footer','tuff_beatz_v1413_panel',13);
function tuff_beatz_v1413_css(){if(!is_page('business-command'))return;wp_add_inline_style('tuff-beatz-business-command','.tb-v1413-trends{margin-top:18px;padding:20px;border:1px solid rgba(216,180,90,.13);border-radius:18px;background:#0a0a0a}.tb-v1413-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;padding-bottom:16px;border-bottom:1px solid rgba(255,255,255,.05)}.tb-v1413-head small,.tb-v1413-kpis small{display:block;color:#8f7744;font-size:.52rem;letter-spacing:.13em}.tb-v1413-head h3{margin:4px 0;color:#dfd6c2;font-family:Cinzel,serif}.tb-v1413-head p{margin:5px 0 0;color:#716a5e;font-size:.6rem}.tb-v1413-head>div:last-child{text-align:right}.tb-v1413-head span,.tb-v1413-head strong{display:block}.tb-v1413-head span{color:#716a5e;font-size:.5rem}.tb-v1413-head strong{margin-top:4px;color:#e3c66d;font:1.2rem Cinzel,serif}.tb-v1413-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.tb-v1413-kpis article{padding:13px;border:1px solid rgba(255,255,255,.05);border-radius:12px;background:rgba(255,255,255,.012)}.tb-v1413-kpis strong,.tb-v1413-kpis span{display:block}.tb-v1413-kpis strong{margin-top:6px;color:#e2c66c;font-family:Cinzel,serif}.tb-v1413-kpis span{margin-top:3px;color:#6e675d;font-size:.53rem}.tb-v1413-table{margin-top:10px;border:1px solid rgba(255,255,255,.05);border-radius:13px;overflow:hidden}.tb-v1413-row{display:grid;grid-template-columns:1.2fr repeat(5,1fr);gap:8px;padding:9px 12px;border-bottom:1px solid rgba(255,255,255,.04);color:#8b8376;font-size:.56rem}.tb-v1413-row:last-child{border-bottom:0}.tb-v1413-row b{color:#d3c9b6}.tb-v1413-row.is-head{background:rgba(216,180,90,.035);color:#9a814b;font-size:.49rem;letter-spacing:.08em;text-transform:uppercase}.tb-v1413-foot{margin:10px 0 0;color:#625c53;font-size:.52rem;line-height:1.5}@media(max-width:900px){.tb-v1413-kpis{grid-template-columns:repeat(2,1fr)}.tb-v1413-head{align-items:flex-start;flex-direction:column}.tb-v1413-head>div:last-child{text-align:left}.tb-v1413-table{overflow-x:auto}.tb-v1413-row{min-width:700px}}@media(max-width:620px){.tb-v1413-kpis{grid-template-columns:1fr}}');}
